// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.DirectAdjacencyMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junitpioneer.jupiter.SetSystemProperty;

/**
 * Gate: DISTINCT planning on index order must not perturb the native engine. With the native engine on and the direct
 * adjacency index active, the optimized plan and the executed native path of DISTINCT queries must be identical whether
 * the stable-order planner is enabled or disabled by its kill switch, no pattern may carry a {@code statementOrder}
 * (which would make the native compiler decline adjacency fast paths), results must be identical, and adjacency lookup
 * hits must not drop.
 */
@SetSystemProperty(key = "rdf4j.lmdb.nativeQueryEngine.enabled", value = "true")
class LmdbDistinctStableOrderAdjacencyTest {

	private static final String NS = "http://example.com/adjgate/";
	private static final ValueFactory F = SimpleValueFactory.getInstance();
	private static final String PREFIX = "PREFIX ex: <" + NS + ">\n";
	private static final int NODES = 1500;

	private static final Pattern PATH_TOKEN = Pattern
			.compile("(nativeExecutionPath|plannedExecutionKind|plannedExecutionEngine)=([A-Za-z0-9_\\-]+)");

	@TempDir
	File dataDir;

	@Test
	void distinctQueriesKeepNativeAndAdjacencyPathsUnchanged() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		config.setExperimentalQueryOptimizations(true);
		LmdbStore store = new LmdbStore(new File(dataDir, "enabled"), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		// The comparison run has experimental optimizations off, so no DISTINCT planning takes place.
		LmdbStoreConfig baselineConfig = new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		baselineConfig.setExperimentalQueryOptimizations(false);
		LmdbStore baselineStore = new LmdbStore(new File(dataDir, "baseline"), baselineConfig);
		SailRepository baselineRepository = new SailRepository(baselineStore);
		baselineRepository.init();
		try {
			load(repository);
			load(baselineRepository);
			assertThat(store.getBackingStore().directAdjacencyStore().buildNowForTest()).isTrue();
			assertThat(baselineStore.getBackingStore().directAdjacencyStore().buildNowForTest()).isTrue();

			Map<String, String> queries = new LinkedHashMap<>();
			queries.put("distinct_subjects", PREFIX + "SELECT DISTINCT ?s WHERE { ?s ex:p1 ?o }");
			queries.put("distinct_predicates", PREFIX + "SELECT DISTINCT ?p WHERE { ?s ?p ?o }");
			queries.put("distinct_star", PREFIX + "SELECT DISTINCT ?s ?o2 WHERE { ?s ex:p1 ?o . ?s ex:p2 ?o2 }");

			for (Map.Entry<String, String> query : queries.entrySet()) {
				Run enabled = run(repository, store, query.getValue());
				Run disabled = run(baselineRepository, baselineStore, query.getValue());

				assertThat(enabled.rows).as(query.getKey() + " results").isEqualTo(disabled.rows);
				assertThat(enabled.rows).as(query.getKey() + " results non-empty").isNotEmpty();
				assertThat(enabled.pathTokens).as(query.getKey() + " native execution path").isNotEmpty();
				assertThat(enabled.pathTokens).as(query.getKey() + " native execution path")
						.isEqualTo(disabled.pathTokens);
				assertThat(enabled.explain).as(query.getKey() + " explain").doesNotContain("statementOrder");
				assertThat(disabled.explain).as(query.getKey() + " explain (planner disabled)")
						.doesNotContain("statementOrder");
				assertThat(enabled.lookupHits).as(query.getKey() + " adjacency lookup hits")
						.isGreaterThanOrEqualTo(disabled.lookupHits);
			}
		} finally {
			repository.shutDown();
			baselineRepository.shutDown();
		}
	}

	private Run run(SailRepository repository, LmdbStore store, String query) {
		try (RepositoryConnection connection = repository.getConnection()) {
			TupleQuery tupleQuery = connection.prepareTupleQuery(QueryLanguage.SPARQL, query);
			long hitsBefore = AdjacencyEngagementTestAccess.lookupHits(store);
			String explain = tupleQuery.explain(Explanation.Level.Executed).toString();
			Map<String, Integer> rows = new LinkedHashMap<>();
			try (var result = tupleQuery.evaluate()) {
				while (result.hasNext()) {
					BindingSet bindingSet = result.next();
					List<String> parts = new ArrayList<>();
					for (String name : new TreeSet<>(bindingSet.getBindingNames())) {
						parts.add(name + "=" + bindingSet.getValue(name));
					}
					rows.merge(parts.toString(), 1, Integer::sum);
				}
			}
			long hits = AdjacencyEngagementTestAccess.lookupHits(store) - hitsBefore;
			return new Run(rows, explain, pathTokens(explain), hits);
		}
	}

	private static List<String> pathTokens(String explain) {
		List<String> tokens = new ArrayList<>();
		Matcher matcher = PATH_TOKEN.matcher(explain);
		while (matcher.find()) {
			tokens.add(matcher.group());
		}
		return tokens;
	}

	private static void load(SailRepository repository) {
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			for (int i = 0; i < NODES; i++) {
				IRI node = F.createIRI(NS, "n" + i);
				conn.add(node, F.createIRI(NS, "p1"), F.createIRI(NS, "n" + ((i + 1) % NODES)));
				conn.add(node, F.createIRI(NS, "p1"), F.createIRI(NS, "n" + ((i + 7) % NODES)));
				conn.add(node, F.createIRI(NS, "p2"), F.createIRI(NS, "n" + ((i * 31 + 3) % NODES)));
			}
			conn.commit();
		}
	}

	private static final class Run {
		private final Map<String, Integer> rows;
		private final String explain;
		private final List<String> pathTokens;
		private final long lookupHits;

		private Run(Map<String, Integer> rows, String explain, List<String> pathTokens, long lookupHits) {
			this.rows = rows;
			this.explain = explain;
			this.pathTokens = pathTokens;
			this.lookupHits = lookupHits;
		}
	}
}
